export type SfSymbolName = keyof typeof SF_SYMBOL_PATHS;

type SfSymbolProps = {
  name: SfSymbolName;
  className?: string;
} & Omit<SVGProps<SVGSVGElement>, "children" | "viewBox" | "xmlns" | "fill">;

export function SfSymbol({ name, className, ...props }: SfSymbolProps) {
  return (
    <svg
      aria-hidden
      className={cn("size-5 shrink-0", className)}
      fill="none"
      viewBox="0 0 20 20"
      xmlns="http://www.w3.org/2000/svg"
      {...props}
    >
      <path
        d={SF_SYMBOL_PATHS[name]}
        fill="currentColor"
        fillRule={
          name === "function" ||
          name === "doc" ||
          name === "textformat.abc" ||
          name === "paintpalette" ||
          name === "plus" ||
          name === "minus" ||
          name === "eyedropper" ||
          name === "playpause" ||
          name === "pause" ||
          name === "play" ||
          name === "backward.end" ||
          name === "forward.end" ||
          name === "pin" ||
          name === "pin.slash" ||
          name === "xmark" ||
          name === "arrow.down.and.line.horizontal.and.arrow.up" ||
          name === "arrow.up.and.line.horizontal.and.arrow.down" ||
          name === "pointer.arrow.ipad.slash" ||
          name === "pointer.arrow.ipad" ||
          name === "pointer.arrow.rays" ||
          name === "pointer.arrow.ipad.rays" ||
          name === "sun.max" ||
          name === "moon"
            ? "nonzero"
            : "evenodd"
        }
      />
    </svg>
  );
}
